var n=`0335-clafoutis`;var t=`world-0335`;var a=`FR`;var r=`western-europe`;var o=8;var s=57;var l={en:`Clafoutis`,ua:`Клафуті`};var d={en:`A traditional France dish made with sour cherry, chicken egg, whole cow milk, all-purpose flour. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: кисла вишня, куряче яйце, цільне коров'яче молоко, пшеничне борошно універсальне. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:5,i:[[`sour-cherry`,600,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`chicken-egg`,4,`pcs`],[`white-granulated-sugar`,140,`g`],[`whole-cow-milk`,380,`ml`],[`all-purpose-flour`,105,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:4,i:[[`unsalted-butter`,20,`g`]]},{en:`Bake in a preheated 180°C oven for about 38 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 38 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:38,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,30,`g`]]}];var u={slug:n,id:t,country:`FR`,region:r,servings:8,minutes:57,title:l,text:d,steps:g};export{a as country,u as default,t as id,s as minutes,r as region,o as servings,n as slug,g as steps,d as text,l as title};